/**
 * TASK: Complete the three DocumentListener methods so the label named
 * "echo" always shows the CURRENT text of the field named "input"
 * converted to upper case.
 *
 * A DocumentListener hears every change to the field's underlying
 * Document: insertUpdate fires when text is added, removeUpdate fires
 * when text is removed, and changedUpdate fires on attribute changes.
 * All three should refresh the echo label the same way.
 *
 * Example: after input.setText("hello") the label reads "HELLO".
 *
 * The components are already created, named, and wired for you.
 */
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

public class EchoUpperPanel extends JPanel implements DocumentListener {

    private final JTextField input = new JTextField(12);
    private final JLabel echo = new JLabel("");

    public EchoUpperPanel() {
        input.setName("input");
        echo.setName("echo");
        add(input);
        add(echo);
        input.getDocument().addDocumentListener(this);
    }

    @Override
    public void insertUpdate(DocumentEvent e) {
        // TODO: refresh the echo label
    }

    @Override
    public void removeUpdate(DocumentEvent e) {
        // TODO: refresh the echo label
    }

    @Override
    public void changedUpdate(DocumentEvent e) {
        // TODO: refresh the echo label
    }
}

