public class EchoUpperPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            EchoUpperPanel panel = new EchoUpperPanel();
            java.awt.Component field = find(panel, "input");
            java.awt.Component label = find(panel, "echo");
            check("field named input exists", true, field instanceof javax.swing.JTextField);
            check("initial echo is empty", "", textOf(label));
            if (field instanceof javax.swing.JTextField) {
                javax.swing.JTextField tf = (javax.swing.JTextField) field;
                tf.setText("hello");
                check("after typing hello", "HELLO", textOf(label));
                tf.setText("Loud and clear");
                check("mixed case input", "LOUD AND CLEAR", textOf(label));
                tf.setText("abc 123 xyz");
                check("digits pass through", "ABC 123 XYZ", textOf(label));
                tf.setText("");
                check("cleared field (removeUpdate)", "", textOf(label));
                tf.setText("echo");
                check("text after clearing", "ECHO", textOf(label));
            } else {
                failures++;
                System.out.println("FAIL  input field not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

